<template>
  <div class="tabs">
    <nav class="tabs_header">
      <div class="logo" id="logo">
        <img :src="collapsed ? logoSmall : logoBig" alt="lscc" />
      </div>
      <a
        class="tab_header"
        v-for="tab in tabTitles"
        :key="tab.title"
        :class="{ selected: tab.title === selectedTitle }"
        @click="clickHandle(tab.title)"
      >
        <div class="inner">
          <div class="icon">
            <i :class="['bx', tab.icon]"></i>
          </div>
          <div class="title" v-if="!collapsed">{{ tab.title }}</div>
        </div>
      </a>
      <a class="subtab" style="bottom: 60px" v-if="admin > 0">
        <div class="inner" @click="$emit('toggleStaff')">
          <div class="icon"><i v-if="staff === true" class="bx bx-home-alt"></i><i v-else class="bx bx-lock-open-alt"></i></div>
        </div>
      </a>
      <a class="subtab">
        <div class="inner" @click="collapse">
          <div class="icon"><i v-if="collapsed" class="bx bx-expand"></i><i v-else class="bx bx-collapse"></i></div>
        </div>
      </a>
    </nav>
    <div class="tab-content">
      <transition name="slide" appear>
        <div v-if="tabTitles.find(({ title }) => title === selectedTitle).top" class="top"></div>
      </transition>
      <div class="bottom max-h-full">
        <slot />
      </div>
    </div>
  </div>
</template>

<script>
import { ref, provide } from "vue";
import $ from "jquery";

export default {
  name: "TabsWrapper",
  props: ["staff", "admin", "collapsed"],
  emits: ["toggleStaff", "collapse"],
  methods: {
    clickHandle(title) {
      this.selectedTitle = title;
    },
    collapse() {
      console.log(`jebo te `);
      $(".tabs_header").toggleClass("collapsed");
      this.$emit("collapse");
    },
  },
  data() {
    return {
      logoBig: require("@/assets/logobig.png"),
      logoSmall: require("@/assets/logo.png"),
      logoURL: `https://cdn.discordapp.com/attachments/890530526509797376/894658481221664848/RNC_COVER_CONCEPT_2.png`,
    };
  },
  setup(props, { slots }) {
    //console.log(slots.default());
    let tabs = slots
      .default()
      .filter((tab) => tab.props)
      .map((tab) => tab.props);
    if (Array.isArray(slots.default()[slots.default().length - 1].children))
      tabs = tabs.concat(slots.default()[slots.default().length - 1].children.map((tab) => tab.props));

    const tabTitles = ref(tabs);

    const selectedTitle = ref(tabTitles.value[0].title);
    //console.log(tabTitles.value);

    provide("selectedTitle", selectedTitle);
    provide("tabTitles", tabTitles);
    return {
      selectedTitle,
      tabTitles,
    };
  },
};
</script>

<style scoped lang="scss">
.collapsed {
  width: 70px !important;
  min-width: 70px !important;

  .logo {
    img {
      width: 50px;
      height: 25px;
    }
  }

  .colap,
  .subtab {
    .inner {
      width: 50px !important;
    }

    .title {
      display: none;
    }
  }

  .tab_header {
    .inner {
      width: 50px !important;
    }
  }
}

.subtab {
  position: absolute;
  display: grid;
  justify-content: center;
  align-items: center;
  z-index: 999;
  margin-bottom: 10px;
  bottom: 0;
  min-width: 100%;

  .inner {
    cursor: pointer;
    transition: 0.4s;
    transition-property: background-color width;
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 10px 23px;
    border-radius: 15px;
    font-size: 17px;
    width: 150px;

    color: #ced6e2a6;
    background: #ced6e221;

    .title {
      opacity: 0;
      animation: fade-in 0.3s cubic-bezier(0.39, 0.575, 0.565, 1) both;
      animation-delay: 0.2s;
    }

    &:hover {
      background: #ced6e244;
    }

    .icon {
      display: grid;
      justify-content: center;
      align-items: center;
      text-align: center;
      width: 42px;

      .bx {
        font-size: 30px;
      }
    }
  }
}

.slide-enter-active {
  animation: slide 0.5s ease-out both;
}

.slide-leave-active {
  animation: slide 0.5s reverse ease-in both;
}

@keyframes slide {
  0% {
    min-height: 0px;
  }
  100% {
    min-height: 60px;
  }
}

.top {
  min-height: 60px;
  display: flex;
  align-items: center;
  font-size: 22px;
  color: #fff;
  //border-bottom: 1px solid $sago-gray2;
  background: $foreground;
  //box-shadow: rgba(0, 0, 0, 0.35) 0px 5px 15px;
}

.bottom {
  background: $background;
  border-radius: 15px;
  flex: 1;
  padding: 10px;
  box-shadow: rgba(0, 0, 0, 0.35) 0px 5px 15px inset;
  overflow: visible !important;
  position: relative;
}

.tab-content {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
}

.animation {
  position: absolute;
  height: 70px;
  width: 100%;
  /* height: 5px; */
  top: 0;
  /* bottom: 0; */
  z-index: 1;
  background: rgba($background, 0.5);
  border-top-left-radius: 10px;
  border-bottom-left-radius: 10px;
  transition: all 0.5s ease 0s;
}

.tabs {
  font-family: "Nunito", sans-serif;
  font-weight: bold;
  display: flex;
  height: 100%;
  width: 100%;
}

.bx {
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 27px;
}

.logo {
  width: 100%;
  height: 60px;
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  //margin: 13px 0px 20px 20px;
  //background: #2d6ae3;

  img {
    width: 150px;
    height: 30px;
    -webkit-user-drag: none;
  }
}

.tabs_header {
  overflow: visible !important;
  height: 100%;
  width: 170px;
  min-width: 170px;
  color: $gray-text;
  position: relative;
  //border-right: 1px solid $sago-gray2;
  font-size: 15px;
  background: $foreground;
  //box-shadow: rgba(0, 0, 0, 0.35) 0px 5px 15px;
  transition: all 0.5s;

  .selected {
    .inner {
      color: $blue !important;
      background: rgba($blue, 0.1);
    }
  }

  .tab_header {
    display: grid;
    justify-content: center;
    align-items: center;
    cursor: pointer;
    z-index: 999;
    position: relative;
    margin-bottom: 5px;

    .title {
      opacity: 0;
      animation: fade-in 0.3s cubic-bezier(0.39, 0.575, 0.565, 1) both;
      animation-delay: 0.2s;
    }

    .inner {
      transition: all 0.4s;
      display: flex;
      justify-content: flex-start;
      align-items: center;
      padding: 10px;
      border-radius: 15px;
      font-size: 17px;
      width: 150px;

      color: #ced6e2a6;

      .icon {
        display: grid;
        justify-content: center;
        align-items: center;
        text-align: center;
        width: 42px;

        .bx {
          font-size: 30px;
        }
      }
    }
  }
}

@keyframes fade-in {
  0% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}
</style>
