<template>
  <div class="panel flex">
    <div class="avatar w-full" @mouseover="hoverAvatar = true" @mouseleave="hoverAvatar = false" @click="avatarChange">
      <transition name="fade">
        <div class="hover" v-if="hoverAvatar">
          Change
        </div>
      </transition>
      <img :src="avatarURL" alt="avatar" />
    </div>
    <div class="info w-full p-3 flex flex-col justify-center">
      <div class="name p-0 leading-6">
        RotX
      </div>
      <div class="progress">
        <div class="levelxp flex justify-between">
          <div class="level">Level: <span>69</span></div>
          <div class="xp">XP: 69/100</div>
        </div>
        <progress class="w-full" max="100" value="69"></progress>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: "ProfileBar",
  methods: {
    randomStr(length) {
      let result = "";
      let characters = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
      let charactersLength = characters.length;
      for (let i = 0; i < length; i++) {
        result += characters.charAt(Math.floor(Math.random() * charactersLength));
      }
      return result;
    },
    async avatarChange() {
      let that = this;
      const { value: type } = await global.Swal.fire({
        title: "Select avatar type",
        input: "select",
        inputOptions: {
          avataaars: "Avataaars",
          bigears: "Big Ears",
          bigearsneutral: "Big Ears Neutral",
          bigsmile: "Big Smile",
          bottts: "Bottts",
          croodles: "Croodles",
          croodlesneutral: "Croodles Neutral",
          gridy: "Gridy",
          identicon: "Identicon",
          initials: "Initials",
          jdenticon: "Jdenticon",
          micah: "Micah",
          miniavs: "Miniavs",
          openpeeps: "Open Peeps",
          personas: "Personas",
          pixelart: "Pixel Art",
          pixelartneutral: "Pixel Art Neutral",
        },
        inputValue: "jdenticon",
        inputPlaceholder: "Avatar types",
        confirmButtonText: "Select",
        showCancelButton: true,
        preConfirm: (data) => {
          if (!data) return global.Swal.showValidationMessage(`You must select an avatar type!`);
        },
        inputValidator: () => {
          return new Promise((resolve) => {
            resolve();
          });
        },
      });

      if (type) {
        let finaltype = type;

        switch (finaltype) {
          case "bigears":
            finaltype = "big-ears";
            break;
          case "bigearsneutral":
            finaltype = "big-ears-neutral";
            break;
          case "bigsmile":
            finaltype = "big-smile";
            break;
          case "croodlesneutral":
            finaltype = "croodles-neutral";
            break;
          case "openpeeps":
            finaltype = "open-peeps";
            break;
          case "pixelart":
            finaltype = "pixel-art";
            break;
          case "pixelartneutral":
            finaltype = "pixel-art-neutral";
            break;
        }

        console.log(finaltype);
        await global.Swal.fire({
          title: "Avatar Seed",
          input: "text",
          inputValue: that.randomStr(8),
          imageUrl: `https://avatars.dicebear.com/api/${finaltype}/0.svg`,
          imageHeight: 150,
          showCancelButton: true,
          showDenyButton: true,
          denyButtonText: `Randomize`,
          confirmButtonText: "Change",
          didOpen: () => {
            const input = global.Swal.getInput();
            global.Swal.getImage().src = `https://avatars.dicebear.com/api/${finaltype}/${input.value}.svg`;
            input.oninput = () => {
              global.Swal.getImage().src = `https://avatars.dicebear.com/api/${finaltype}/${input.value}.svg`;
            };
          },
          preConfirm: (data) => {
            if (!data || data.length < 1 || data.length > 10) return global.Swal.showValidationMessage(`Seed must be between 1 and 10 characters.`);
          },
          preDeny: () => {
            let random = that.randomStr(8);
            global.Swal.getInput().value = random;
            global.Swal.getImage().src = `https://avatars.dicebear.com/api/${finaltype}/${random}.svg`;
            return false;
          },
        }).then((result) => {
          if (result.isConfirmed) {
            console.log(`https://avatars.dicebear.com/api/${finaltype}/${result.value}.svg`);
            that.avatarURL = `https://avatars.dicebear.com/api/${finaltype}/${result.value}.svg`;
          }
        });
      }
    },
  },
  data() {
    return {
      seed: "",
      hoverAvatar: false,
      avatarURL: "https://avatars.dicebear.com/api/pixel-art/2fasfsaf.svg",
    };
  },
};
</script>

<style scoped lang="scss">
.progress {
  progress[value] {
    height: 30px;

    &::-webkit-progress-bar {
      border-radius: 15px;
      background-color: $gray;
      border: 2px solid lighten($gray, 5%);
    }

    &::-webkit-progress-value {
      border-radius: 15px;
      background-color: $blue;
    }
  }
}

.fade-enter-active {
  animation: fade 0.2s cubic-bezier(0.39, 0.575, 0.565, 1) both;
}

.fade-leave-active {
  animation: fade 0.2s cubic-bezier(0.39, 0.575, 0.565, 1) both reverse;
}

.panel {
  background: $foreground;
  color: $white-text;
  border-radius: 15px;
  padding: 5px;

  .name {
    font-size: 25px;
    font-weight: bold;
  }

  .avatar {
    width: 120px;
    min-width: 120px;
    height: 120px;
    border: 2px solid lighten($foreground, 20%);
    border-radius: 15px;
    position: relative;

    .hover {
      background: rgba(darken($foreground, 50%), 0.5);
      position: absolute;
      width: 100%;
      height: 100%;
      display: flex;
      justify-content: center;
      align-items: center;
      font-size: 20px;
      text-transform: uppercase;
      font-weight: bolder;
      border-radius: 15px;
    }
  }
}

@keyframes fade {
  0% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}
</style>
