<template>
  <div class="grid gap-5 overflow-y-scroll max-h-full max-w-full p-5">
    <template v-for="option in options">
      <ToggleOption
        v-if="option.type === 1"
        :key="option.name"
        :id="option.id"
        :label="option.label"
        :name="option.name"
        :description="option.description"
        :ref="option.name"
      />

      <RadioOption
        v-else-if="option.type === 2"
        :key="option.name"
        :id="option.id"
        :label="option.label"
        :name="option.name"
        :description="option.description"
        :options="option.options"
        :ref="option.name"
      />

      <BindOption
        v-else-if="option.type === 3"
        :key="option.name"
        :id="option.id"
        :label="option.label"
        :name="option.name"
        :description="option.description"
        :ref="option.name"
      />

      <SelectOption
        v-else-if="option.type === 4"
        :key="option.name"
        :id="option.id"
        :label="option.label"
        :name="option.name"
        :description="option.description"
        :options="option.options"
        :ref="option.name"
        :preSelect="option.preSelect ? option.preSelect : null"
      />
    </template>
  </div>
</template>

<script>
/*
Types: 1 = toggle | 2 = radio | 3 = bind
*/

import ToggleOption from "./ToggleOption";
import RadioOption from "./RadioOption";
import BindOption from "./BindOption";
import SelectOption from "./SelectOption";

export default {
  name: "Settings",
  props: ["options"],
  components: {
    ToggleOption,
    RadioOption,
    BindOption,
    SelectOption,
  },
};
</script>

<style lang="scss">
:root {
  --toggle-bg-on: rgb(91, 145, 254);
  --toggle-border-on: rgb(91, 145, 254);

  --toggle-bg-off: transparent;
  --toggle-border-off: rgb(78, 78, 78);
  --toggle-ring-width: 0px;
}
</style>
