<template>
  <div class="w-full ">
    <div class="flex flex-wrap justify-center">
      <div class="m-1">
        <CustomSelect
          @change="changeType"
          :placeholder="'Select type'"
          :preSelect="preSelect"
          :options="options"
          :id="'staffLogsSelect'"
          ref="select"
        />
      </div>
      <input @focus="isFocus(true)" @blur="isFocus(false)" v-model="query" placeholder="Player" class="query m-1" type="text" />
    </div>
    <div class="flex w-full justify-center p-2">
      <button @click="search" class="font-bold text-lg search flex" :disabled="isLoading === true">
        <i v-if="isLoading === true" class="bx bx-loader-alt fa-spin text-lg mr-0.5"></i><i v-else class="bx bx-search text-lg mr-0.5"></i> Search
      </button>
    </div>
    <div class="flex w-full justify-center p-2 overflow-y-auto" style="max-height: 650px;">
      <Table :rows="devMode ? devRows : rows" :columns="devMode ? devColumns : columns" />
    </div>
  </div>
</template>

<script>
import CustomSelect from "../../components/CustomSelect.vue";
import Table from "../../components/custom/Table.vue";

export default {
  name: "LogsTab",
  props: ["devMode"],
  components: { CustomSelect, Table },
  data() {
    return {
      type: "",
      query: "",
      preSelect: "Admin",
      options: [
        { name: "Sessions", value: "sessions" },
        { name: "Admin", value: "admin" },
        { name: "Records", value: "records" },
      ],
      rows: [],
      devRows: ["Reason", "Duration", "Timestamp"],
      columns: [],
      devColumns: [
        ["cheating", "30 minutes.", "2021-09-11 23:28:25"],
        ["(#1) Insulting", "10 minutes.", "2021-09-12 12:10:39"],
        ["(#1) Being toxic + Insulting people", "N/A", "2021-09-12 13:24:42"],
        ["Hacks + Aimbot", "999999999 minutes.", "2021-09-12 15:25:43"],
        ["(#1) Ramming", "1 minute.", "2021-09-12 15:25:47"],
        ["(#2) VDM", "N/A", "2021-09-12 19:11:28"],
        ["cheating", "30 minutes.", "2021-09-11 23:28:25"],
        ["(#1) Insulting", "10 minutes.", "2021-09-12 12:10:39"],
        ["(#1) Being toxic + Insulting people", "N/A", "2021-09-12 13:24:42"],
        ["Hacks + Aimbot", "999999999 minutes.", "2021-09-12 15:25:43"],
        ["(#1) Ramming", "1 minute.", "2021-09-12 15:25:47"],
        ["(#2) VDM", "N/A", "2021-09-12 19:11:28"],
        ["(#1) Being toxic + Insulting people", "N/A", "2021-09-12 13:24:42"],
        ["Hacks + Aimbot", "999999999 minutes.", "2021-09-12 15:25:43"],
        ["(#1) Ramming", "1 minute.", "2021-09-12 15:25:47"],
        ["(#2) VDM", "N/A", "2021-09-12 19:11:28"],
        ["(#1) Being toxic + Insulting people", "N/A", "2021-09-12 13:24:42"],
        ["Hacks + Aimbot", "999999999 minutes.", "2021-09-12 15:25:43"],
        ["(#1) Ramming", "1 minute.", "2021-09-12 15:25:47"],
        ["(#2) VDM", "N/A", "2021-09-12 19:11:28"],
      ],
      isLoading: false,
      cooldown: 1500,
    };
  },
  methods: {
    changeType(type) {
      console.log("type", type);
      this.type = type;
    },
    search() {
      // eslint-disable-next-line no-undef
      mp.trigger("RequestLogsFromServer", this.type, this.query);
      this.isLoading = true;
      setTimeout(() => {
        this.isLoading = false;
      }, this.cooldown);
    },
    isFocus(value) {
      // eslint-disable-next-line no-undef
      mp.trigger("ScoreboardToggleTyping", value);
    },
  },
};
</script>

<style lang="scss" scoped>
.query {
  color: lighten($gray, 30%);
  background: darken($gray, 10%);
  border-radius: 5px;
  font-weight: bold;
  font-size: 18px;
  padding: 10px 20px;
  width: 200px;
  border: 2px solid $gray;

  &::placeholder {
    color: lighten($gray, 30%);
  }

  &:focus {
    outline: none;
  }
}

.search {
  color: #ced6e2a6;
  background: #ced6e221;
  padding: 10px 23px;
  border-radius: 15px;
  font-weight: bold;
  transition: all 0.4s;

  &[disabled] {
    pointer-events: none;
    background: #ced6e244;
  }

  &:hover {
    background: #ced6e244;
  }
}
</style>
