<template>
  <SettingsTabsWrapper ref="selector" :key="renderKey">
    <SettingTab v-for="category in devMode ? devCategories : categories" :key="category" :title="category.name">
      <Settings :options="category.settings" :ref="category.name" />
    </SettingTab>
  </SettingsTabsWrapper>
</template>

<script>
import SettingsTabsWrapper from "./SettingsTabsWrapper";
import SettingTab from "./SettingTab";
import Settings from "./Settings";
export default {
  name: "SettingsTab",
  props: ["devMode"],
  components: { Settings, SettingTab, SettingsTabsWrapper },
  data() {
    return {
      categories: [{ name: "default" }],
      devCategories: Array(this.getRndInt(2, 5))
        .fill()
        .map(() => ({
          name: this.makeid(5),
          settings: Array(this.getRndInt(10, 20))
            .fill()
            .map(() => {
              switch (this.getRndInt(1, 5)) {
                case 1:
                  return {
                    id: this.getRndInt(1, 2000),
                    type: 1,
                    name: this.makeid(5),
                    label: this.makeid(5),
                    description: this.makeid(20),
                  };
                case 2:
                  return {
                    id: this.getRndInt(1, 2000),
                    type: 2,
                    name: this.makeid(5),
                    label: this.makeid(5),
                    description: this.makeid(20),
                    options: Array(this.getRndInt(3, 10))
                      .fill()
                      .map(() => ({ name: this.makeid(5), value: this.makeid(5) })),
                  };
                case 3:
                  return {
                    id: this.getRndInt(1, 2000),
                    type: 3,
                    name: this.makeid(5),
                    label: this.makeid(5),
                    description: this.makeid(20),
                  };
                case 4:
                  return {
                    id: this.getRndInt(1, 2000),
                    type: 4,
                    name: this.makeid(5),
                    label: this.makeid(5),
                    description: this.makeid(20),
                    options: Array(this.getRndInt(3, 10))
                      .fill()
                      .map(() => ({ name: this.makeid(5), value: this.makeid(5) })),
                  };
              }
            }),
        })),
      renderKey: 0,
    };
  },
  watch: {
    categories: {
      handler() {
        this.renderKey++;
      },
      deep: true,
    },
  },
  mounted() {
    //wait 5 sec
  },
  methods: {
    makeid(length) {
      var result = "";
      var characters = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
      var charactersLength = characters.length;
      for (var i = 0; i < length; i++) {
        result += characters.charAt(Math.floor(Math.random() * charactersLength));
      }
      return result;
    },
    getRndInt(min, max) {
      return Math.floor(Math.random() * (max - min)) + min;
    },
  },
};
</script>

<style scoped lang="scss">
* {
  overflow: visible !important;
}
</style>
